210	/// Read and validate the JSON request body into a [`RunRequest`].
211	///
212	/// Performs a lightweight content-type check: returns 400 on an explicit
213	/// non-JSON content type, while a missing content type is tolerated and the
214	/// bytes are parsed optimistically.
215	async fn read_run_request(parts: &Parts, body: Body) -> Result<RunRequest, ServerError> {
216	    if let Some(ct) = parts
217	        .headers
218	        .get(CONTENT_TYPE)
219	        .and_then(|v| v.to_str().ok())
220	    {
221	        let mime = ct.split(';').next().unwrap_or("").trim();
222	        let is_json = mime == "application/json"
223	            || (mime.starts_with("application/") && mime.ends_with("+json"));
224	        if !is_json {
225	            return Err(ServerError::BadRequest(format!(
226	                "unsupported content type `{mime}`; expected application/json"
227	            )));
228	        }
229	    }
230	
231	    let bytes = axum::body::to_bytes(body, MAX_BODY_BYTES)
232	        .await
233	        .map_err(|e| ServerError::BadRequest(format!("failed to read request body: {e}")))?;
234	
235	    serde_json::from_slice::<RunRequest>(&bytes)
236	        .map_err(|e| ServerError::BadRequest(format!("invalid run request body: {e}")))
237	}
