239	/// Drop-guard that records a run's terminal bookkeeping exactly once — on the
240	/// normal path **and** on a panic unwind of the writer task.
241	///
242	/// Both operations are idempotent: [`EventLog::mark_terminal`] just sets a flag,
243	/// and [`RunRegistry::note_terminal`] only stamps when `terminal_at` is still
244	/// `None`. Without this guard a panic mid-drain (e.g. a faulty agent stream)
245	/// would strand every subscriber waiting forever.
246	struct TerminalGuard {
247	    log: Arc<EventLog>,
248	    registry: Arc<RunRegistry>,
249	    run_id: Uuid,
250	}
251	
252	impl Drop for TerminalGuard {
253	    fn drop(&mut self) {
254	        self.log.mark_terminal();
255	        self.registry.note_terminal(self.run_id, Instant::now());
256	    }
257	}
258	
259	/// Spawn the detached writer task that drives one run to completion.
260	///
261	/// Owns every input by value so the task satisfies `'static`. Holds the session
262	/// lock `guard` for the whole run and drops it (releasing the lock) once the run
263	/// is terminal and recorded in the registry. Terminal bookkeeping is owned by a
264	/// [`TerminalGuard`] so it still happens if the agent stream panics mid-drain.
265	#[allow(clippy::too_many_arguments)]
266	fn spawn_writer<Ctx: Send + Sync + 'static>(
267	    runner: Arc<dyn Runner<Ctx>>,
268	    agent: Arc<dyn Agent<Ctx>>,
269	    ctx: RunContext<Ctx>,
270	    input: AgentInput,
271	    run_config: RunConfig,
272	    handle: Arc<RunHandle>,
273	    registry: Arc<RunRegistry>,
274	    run_id: Uuid,
275	    guard: OwnedMutexGuard<()>,
276	) {
277	    tokio::spawn(async move {
278	        // Declared FIRST so it drops LAST: terminal bookkeeping (below) runs
279	        // before the session lock is released, preserving the original ordering.
280	        let _session_lock = guard;
281	        // Declared AFTER the lock so it drops FIRST. Its `Drop` marks the log
282	        // terminal and stamps the registry — even on a panic unwind.
283	        let _terminal = TerminalGuard {
284	            log: Arc::clone(&handle.log),
285	            registry,
286	            run_id,
287	        };
288	
289	        match runner
290	            .run_streamed(agent.as_ref(), ctx, input, run_config)
291	            .await
292	        {
293	            Ok(streaming) => {
294	                let mut events = streaming.events;
295	                while let Some(ev) = events.next().await {
296	                    handle.log.append(ev);
297	                }
298	                // Terminal marking is handled by `_terminal` on scope exit; a
299	                // real `RunCompleted`/`RunFailed` already set the flag, and the
300	                // guard's `mark_terminal` is an idempotent safety net otherwise.
301	            }
302	            Err(e) => {
303	                // The run failed to *start* (no events were ever emitted). Record
304	                // the cause; `_terminal` marks the log terminal so subscribers
305	                // unblock.
306	                *handle
307	                    .start_error
308	                    .lock()
309	                    .expect("start_error mutex poisoned") = Some(e.to_string());
310	            }
311	        }
312	    });
313	}
