315	/// Build the `202 Accepted` body for a detached run.
316	fn async_response(run_id: Uuid) -> Response {
317	    (
318	        StatusCode::ACCEPTED,
319	        Json(AsyncAccepted {
320	            run_id: run_id.to_string(),
321	        }),
322	    )
323	        .into_response()
324	}
