326	/// Unfold state for the SSE response stream: the live event stream, the cancel
327	/// drop-guard (held for the stream's whole lifetime so a client disconnect
328	/// cancels the run), a clone of the run handle (to synthesize a terminal frame
329	/// on a terminal-less close), and the `saw_terminal` / `done` flags.
330	struct SseState<S> {
331	    events: S,
332	    // Held only for its `Drop` side effect (cancels the run when the SSE
333	    // response — and with it this state — is dropped); never read directly.
334	    #[allow(dead_code)]
335	    disconnect: DropGuard,
336	    handle: Arc<RunHandle>,
337	    saw_terminal: bool,
338	    done: bool,
339	}
340	
341	/// Build the SSE streaming response.
342	///
343	/// The run's cancel `DropGuard` is folded into the stream state so that dropping
344	/// the response (a client disconnect) cancels the run. If the live event stream
345	/// ends without delivering a real terminal event (a start-error, or a stream
346	/// that ended/panicked mid-run), exactly one synthetic `run_failed` frame is
347	/// appended before the SSE stream closes — see
348	/// [`RunHandle::synthetic_terminal_frame`].
349	fn sse_response(run_id: Uuid, handle: &Arc<RunHandle>) -> Response {
350	    let disconnect = handle.cancel.clone().drop_guard();
351	    let events = handle.log.subscribe(0);
352	    let handle = Arc::clone(handle);
353	
354	    let stream = futures_util::stream::unfold(
355	        SseState {
356	            events,
357	            disconnect,
358	            handle,
359	            saw_terminal: false,
360	            done: false,
361	        },
362	        |mut state| async move {
363	            if state.done {
364	                return None;
365	            }
366	            match state.events.next().await {
367	                Some(ev) => {
368	                    state.saw_terminal |= is_terminal(&ev);
369	                    let frame = to_sse_event(&ev);
370	                    Some((Ok::<Event, Infallible>(frame), state))
371	                }
372	                None => {
373	                    // Live stream ended. If no real terminal was delivered, emit
374	                    // exactly one synthetic `run_failed` frame, then finish.
375	                    let synthetic = state.handle.synthetic_terminal_frame(state.saw_terminal)?;
376	                    let frame = to_sse_event(&synthetic);
377	                    state.done = true;
378	                    Some((Ok::<Event, Infallible>(frame), state))
379	                }
380	            }
381	        },
382	    );
383	
384	    let mut response = Sse::new(stream).into_response();
385	    insert_run_id(response.headers_mut(), run_id);
386	    response
387	}
388	
389	/// Build the one-shot response: subscribe, drain to the terminal event, then
390	/// aggregate into a [`RunResponse`].
391	async fn oneshot_response(run_id: Uuid, handle: &Arc<RunHandle>) -> Result<Response, ServerError> {
392	    // Cancel the run if the client disconnects while we await the result.
393	    let _disconnect = handle.cancel.clone().drop_guard();
394	
395	    // NOTE: the event log is capped at `max_events_per_run` events; `output`
396	    // in the response reflects only the events retained by the ring buffer.
397	    let events: Vec<AgentEvent> = handle.log.subscribe(0).collect().await;
398	
399	    // If the run failed to *start*, surface a 500 rather than a 200 envelope.
400	    if let Some(msg) = handle
401	        .start_error
402	        .lock()
403	        .expect("start_error mutex poisoned")
404	        .clone()
405	    {
406	        return Err(ServerError::RunStart(msg));
407	    }
408	
409	    let mut response = Json(RunResponse::from_events(run_id, events)).into_response();
410	    insert_run_id(response.headers_mut(), run_id);
411	    Ok(response)
412	}
413	
414	/// Serialize an [`AgentEvent`] into an SSE [`Event`], tagging the SSE `event:`
415	/// field with the event's serde `type` discriminant and carrying the full event
416	/// JSON as the `data:` payload.
417	fn to_sse_event(ev: &AgentEvent) -> Event {
418	    let value = serde_json::to_value(ev).expect("AgentEvent serializes");
419	    let event = match value.get("type").and_then(serde_json::Value::as_str) {
420	        Some(tag) => Event::default().event(tag),
421	        None => Event::default(),
422	    };
423	    event
424	        .json_data(&value)
425	        .expect("serde_json::Value serializes without error")
426	}
427	
428	/// Insert the `X-Run-Id` response header.
429	fn insert_run_id(headers: &mut HeaderMap, run_id: Uuid) {
430	    let value =
431	        HeaderValue::from_str(&run_id.to_string()).expect("uuid is always a valid header value");
432	    headers.insert("x-run-id", value);
433	}
