115	/// Post-run finalization: drain the recorder and append the run's events.
116	/// Persistence is best-effort — an append error is logged, never propagated, so
117	/// the run's outcome (Ok / Cancelled / Timeout / Agent error) is unchanged.
118	async fn finalize(session: &Arc<dyn Session>, recorder: &Arc<Mutex<SessionRecorder>>) {
119	    let events = recorder
120	        .lock()
121	        .expect("session recorder mutex poisoned")
122	        .drain();
123	    if let Err(e) = session.append(&events).await {
124	        tracing::warn!(
125	            error = %e,
126	            "session persistence failed during finalize; run outcome unaffected"
127	        );
128	    }
129	}
