131	/// The default ephemeral execution backend. Stateless.
132	#[derive(Debug, Clone, Copy, Default)]
133	pub struct TokioRunner;
134	
135	#[async_trait]
136	impl<Ctx> Runner<Ctx> for TokioRunner
137	where
138	    Ctx: Send + Sync + 'static,
139	{
140	    async fn run(
141	        &self,
142	        agent: &(dyn Agent<Ctx> + '_),
143	        ctx: RunContext<Ctx>,
144	        input: AgentInput,
145	        config: RunConfig,
146	    ) -> Result<RunResult, RunError> {
147	        let timeout = config.timeout;
148	        let ctx = ctx.with_run_config(config);
149	        let cancel = ctx.cancel().clone();
150	        let session = ctx.session().clone();
151	        let failure = ctx.failure_handle();
152	
153	        // Load persisted history and seed the recorder with the new turn.
154	        let (merged, recorder) = load_and_record(&session, agent.name(), input).await?;
155	
156	        let stream = agent.run(ctx, merged).await?;
157	        let (controlled_stream, outcome) = controlled(stream, cancel, timeout);
158	        let rec_inspect = Arc::clone(&recorder);
159	        let recorded = controlled_stream
160	            .inspect(move |ev| {
161	                rec_inspect
162	                    .lock()
163	                    .expect("session recorder mutex poisoned")
164	                    .observe(ev)
165	            })
166	            .boxed();
167	        // Do NOT `?`-short-circuit before finalize: agent failures surface as
168	        // collect()=Err, and finalize must still run.
169	        let collected = RunResultStreaming::with_failure(recorded, failure)
170	            .collect()
171	            .await;
172	        finalize(&session, &recorder).await;
173	
174	        // A genuine terminal event (RunCompleted/RunFailed) is the run's true
175	        // outcome; a cancel/timeout overrides ONLY when no terminal was observed
176	        // — i.e. it actually aborted the run in-flight. This closes the window
177	        // where a late cancel (e.g. during a suspending OnRunComplete hook) fires
